		private bool ItemEff_Mental_Cure(global::Dpr.Battle.Logic.BTL_POKEPARAM bpp, ushort itemID, int itemParam, global::Pml.WazaData.WazaSick sickID) {
			if (bpp.IsDead() || GetBattleEnv().GetPosPoke().IsExist(bpp.GetID()))
				return false;
			bool isCured = false;
			uint idx = 0;
			WazaSick sick;
			while ((sick = tables.GetMentalSickID(idx++)) != WazaSick.WAZASICK_NONE)
			{
				if (!bpp.CheckSick(sick))
					continue;
				byte pokeID = bpp.GetID();
				Section_CureSick.Result result = new Section_CureSick.Result();
				Section_CureSick.Description desc = new Section_CureSick.Description();
				desc.targetPokeCount = 1;
				desc.pokeID = pokeID;
				desc.targetPokeID[0] = pokeID;
				desc.sick = (WazaSickEx)sick;
				GetSectionContainer().GetSection_CureSick().Execute(result, desc);
				isCured = true;
			}
			return isCured;
		}
