		private bool ItemEff_Relive(global::Dpr.Battle.Logic.BTL_POKEPARAM bpp, ushort itemID, int itemParam, byte actParam) {
			if (!bpp.IsDead())
				return false;
			byte pokeID = bpp.GetID();
			ushort recoverHP;
			switch (calc.ITEM_GetParam(itemID, Pml.Item.ItemData.PrmID.HP_RCV_POINT))
			{
				case 253: // quarter
					recoverHP = (ushort)calc.QuotMaxHP(bpp, 4, false);
					break;
				case 254: // half
					recoverHP = (ushort)calc.QuotMaxHP(bpp, 2, false);
					break;
				case 255: // full
					recoverHP = (ushort)bpp.GetValue(BTL_POKEPARAM.ValueID.BPP_MAX_HP);
					break;
				default:
					recoverHP = (ushort)calc.ITEM_GetParam(itemID, Pml.Item.ItemData.PrmID.HP_RCV_POINT);
					break;
			}
			Section_Relive.Result result = new Section_Relive.Result();
			Section_Relive.Description desc = new Section_Relive.Description();
			desc.pokeID = pokeID;
			desc.recoverHP = recoverHP;
			desc.reliveMessage.Setup(BtlStrType.BTL_STRTYPE_SET, (ushort)BTL_STRID_SET.Relive);
			desc.reliveMessage.AddArg(pokeID);
			GetSectionContainer().GetSection_Relive().Execute(result, desc);
			return true;
		}
