				return false;
			byte pokeID = bpp.GetID();
			byte ppShort = bpp.WAZA_GetPPShort_Org(actParam);
			uint recoverPP = (uint)calc.ITEM_GetParam(itemID, Pml.Item.ItemData.PrmID.PP_RCV_POINT);
			if (recoverPP >= ppShort || recoverPP == 127) // 127 = recover all
				recoverPP = ppShort;
			if ((byte)recoverPP == 0)
				return false;
			Section_FromEvent_RecoverPP.Result result = new Section_FromEvent_RecoverPP.Result();
			Section_FromEvent_RecoverPP.Description desc = new Section_FromEvent_RecoverPP.Description();
			desc.volume = (byte)recoverPP;
			desc.pokeID = pokeID;
			desc.wazaIdx = actParam;
			desc.isDeadPokeEnable = true;
			desc.successMessage.Setup(BtlStrType.BTL_STRTYPE_SET, (ushort)BTL_STRID_SET.PP_Recover);
			desc.successMessage.AddArg(pokeID);
			desc.successMessage.AddArg((int)bpp.WAZA_GetID_Org(actParam));
			GetSectionContainer().GetSection_FromEvent_RecoverPP().Execute(result, desc);
			return true;
		}
