					continue;
				Section_FromEvent_RecoverPP.Result result = new Section_FromEvent_RecoverPP.Result();
				Section_FromEvent_RecoverPP.Description desc = new Section_FromEvent_RecoverPP.Description();
				isRecovered = true;
				desc.wazaIdx = (byte)i;
				desc.pokeID = pokeID;
				desc.volume = volume;
				desc.isDeadPokeEnable = true;
				GetSectionContainer().GetSection_FromEvent_RecoverPP().Execute(result, desc);
			}
			if (!isRecovered)
				return false;
			Section_FromEvent_Message.Result msgResult = new Section_FromEvent_Message.Result();
			Section_FromEvent_Message.Description msgDesc = new Section_FromEvent_Message.Description();
			msgDesc.pokeID = pokeID;
			msgDesc.message.Setup(BtlStrType.BTL_STRTYPE_SET, (ushort)BTL_STRID_SET.PP_AllRecover);
			msgDesc.message.AddArg(pokeID);
			GetSectionContainer().GetSection_FromEvent_Message().Execute(msgResult, msgDesc);
			return true;
		}
		private bool ItemEff_HP_Rcv(global::Dpr.Battle.Logic.BTL_POKEPARAM bpp, ushort itemID, int itemParam, byte actParam) {
			if (bpp.IsHPFull() || bpp.IsDead())
				return false;
			uint recoverHP;
			int param = calc.ITEM_GetParam(itemID, Pml.Item.ItemData.PrmID.HP_RCV_POINT);
			if (param == 253) // quarter
				recoverHP = calc.QuotMaxHP(bpp, 4, true);
			else if (param == 254) // half
				recoverHP = calc.QuotMaxHP(bpp, 2, true);
			else if (param == 255) // full
				recoverHP = (uint)bpp.GetValue(BTL_POKEPARAM.ValueID.BPP_MAX_HP);
			else
				recoverHP = (uint)param;
			makeCmd_RecoverHP(bpp, recoverHP, true);
			if (GetFriendship(bpp) == 255)
			{
				byte pokeID = bpp.GetID();
				Section_FromEvent_FriendshipEffect.Result result = new Section_FromEvent_FriendshipEffect.Result();
				Section_FromEvent_FriendshipEffect.Description desc = new Section_FromEvent_FriendshipEffect.Description();
				desc.pokeID = pokeID;
				desc.effectType = FriendshipEffect.FREFF_FURIMUKI;
				desc.message.Setup(BtlStrType.BTL_STRTYPE_STD, (ushort)BTL_STRID_STD.FR_ItemRecover);
				desc.message.AddArg(pokeID);
				desc.message.AddArg(MainModule.PokeIDtoClientID(pokeID));
				GetSectionContainer().GetSection_FromEvent_FriendshipEffect().Execute(result, desc);
			}
			return true;
		}
		private void makeCmd_RecoverHP(global::Dpr.Battle.Logic.BTL_POKEPARAM bpp, uint recoverHP, bool bStdMsg) {
			byte pokeID = bpp.GetID();
			Section_RecoverHP.Result result = new Section_RecoverHP.Result();
			Section_RecoverHP.Description desc = new Section_RecoverHP.Description();
			desc.userPokeID = pokeID;
			desc.targetPokeID = pokeID;
			desc.isSkipFailCheckSP = true;
			desc.recoverHP = (ushort)recoverHP;
			if (bStdMsg)
			{
				desc.successMessage.Setup(BtlStrType.BTL_STRTYPE_SET, (ushort)BTL_STRID_SET.HP_Recover);
				desc.successMessage.AddArg(pokeID);
			}
			GetSectionContainer().GetSection_RecoverHP().Execute(result, desc);
		}
